public class TreeTraversals {
    static class Node { int val; Node left, right; Node(int v){val=v;} }
    // Inorder: Left → Root → Right
    void inorder(Node root) {
        if (root == null) return;
        inorder(root.left);
        System.out.print(root.val + " ");
        inorder(root.right);
    }
    // Preorder: Root → Left → Right
    void preorder(Node root) {
        if (root == null) return;
        System.out.print(root.val + " ");
        preorder(root.left);
        preorder(root.right);
    }
    // Postorder: Left → Right → Root
    void postorder(Node root) {
        if (root == null) return;
        postorder(root.left);
        postorder(root.right);
        System.out.print(root.val + " ");
    }
    public static void main(String[] args) {
        Node root = new Node(4);
        root.left = new Node(2); root.right = new Node(6);
        root.left.left = new Node(1); root.left.right = new Node(3);
        root.right.left = new Node(5); root.right.right = new Node(7);
        TreeTraversals t = new TreeTraversals();
        t.inorder(root);   System.out.println();
        t.preorder(root);  System.out.println();
        t.postorder(root); System.out.println();
    }
}

